#include <iostream>
#include <vector>
class Buffer {
public:
    std::vector<int> data;
    Buffer() = default;
    Buffer(const Buffer& other) : data(other.data) {
        std::cout << "Copy constructor" << std::endl;
    }
    Buffer(Buffer&& other) noexcept : data(std::move(other.data)) {
        std::cout << "Move constructor" << std::endl;
    }
};

void processBuffer(Buffer&& buf) {
    // Use move semantics to take ownership of buf's resources
    Buffer localBuffer = std::move(buf);
